exercises.solution_py:
for dia in range(1, 8):
    gasto = int(input("¿Cuánto se gastó ese día? "))
    if gasto > 8000:
        print("El día", dia, "se pasó del presupuesto.")
        break

atendidas = 0
while atendidas < 20:
    persona = input("¿Quién llega? ")
    if persona == "sin credencial":
        print("No puede ser atendida, sigue la fila.")
        continue
    if persona == "cierre":
        break
    atendidas = atendidas + 1
print("Se atendió a", atendidas, "personas.")

